using CSharpModBase;using ReadyM.Api.DI;using ReadyM.Api.Multiplayer.Client;using WukongMp.Api.UI;namespace WukongMp.Api;internal class PingWidgetUpdater(NetworkPingMonitor pingMonitor, WukongWidgetManager widgetManager) : IHostedService{    public void OnScopeStart()    {        pingMonitor.OnPingUpdated += HandlePingUpdated;    }    public void Dispose()    {        pingMonitor.OnPingUpdated -= HandlePingUpdated;    }        private void HandlePingUpdated(int pingMs)    {        var packetLossPercent = pingMonitor.PacketLossPercent;        Utils.TryRunOnGameThread(() => { widgetManager.UpdatePingIndicator(pingMs, packetLossPercent); });    }}